// Parse la réponse Claude et fusionne avec les données email originales
const claudeResponse = JSON.parse($input.item.json.content[0].text);
const emailData = $input.item.json;

return {
  json: {
    from: emailData.from,
    subject: emailData.subject,
    snippet: emailData.snippet,
    messageId: emailData.id,
    categorie: claudeResponse.categorie,
    raison: claudeResponse.raison,
    draft_reponse: claudeResponse.draft_reponse
  }
};

// Agrège tous les emails classés en un résumé unique pour notification
const items = $input.all();
const urgent = items.filter(i => i.json.categorie === 'URGENT');
const aTraiter = items.filter(i => i.json.categorie === 'A_TRAITER');
const archiver = items.filter(i => i.json.categorie === 'ARCHIVER');

const summary = `📬 BRIEF EMAIL DU MATIN\n\n🔴 URGENT (${urgent.length}): ${urgent.map(i => i.json.subject).join(', ') || 'aucun'}\n\n🟡 À TRAITER (${aTraiter.length}): ${aTraiter.map(i => i.json.subject).join(', ') || 'aucun'}\n\n⚪ ARCHIVÉ (${archiver.length}) — pas d'action requise`;

return { json: { summary } };
